/**
 * The trajectory solver — SPEC.md §8.1 and §8.3.
 *
 * Point-mass integration with RK4, in three dimensions so that wind drift falls
 * out of the same solver as drop rather than being bolted on as a correction.
 *
 * ── Why we write our own ───────────────────────────────────────────────────
 * SPEC.md §8.3: we do not take a dependency. The open-source implementations
 * are a **validation corpus** in the test suite instead, which is what lets the
 * site claim accuracy rather than assert it. `trajectory.test.ts` checks this
 * solver against a reference trajectory generated by py-ballisticcalc and
 * against two manufacturer-published tables, and states the tolerance it holds
 * to.
 *
 * ── The model, stated so a reader can disagree with it ─────────────────────
 * Drag acts along the projectile's velocity *relative to the air*, with
 * magnitude taken from the standard drag function scaled by the ballistic
 * coefficient. Gravity is constant and vertical. What is deliberately **not**
 * modelled: spin drift, Coriolis, aerodynamic jump and the vertical component
 * of a crosswind. Each needs inputs this site does not record — latitude, firing
 * azimuth, gyroscopic stability — and inventing them to produce a
 * more-decimal-places answer would be exactly the failure this project exists
 * to avoid. Their combined effect is small compared with the uncertainty in a
 * published muzzle velocity at any range a small arm is used at.
 *
 * Pure. No DOM, no I/O, no framework import.
 */
import { KG_PER_POUND, MM_PER_INCH, STANDARD_GRAVITY_MS2 } from '../units.ts';
import {
  dragCoefficient,
  machOf,
  STANDARD_ATMOSPHERE,
  type Atmosphere,
  type DragModel,
} from './drag.ts';

/**
 * Frontal area over mass for the standard projectile — one pound, one inch in
 * diameter — which is the quantity a ballistic coefficient is a ratio against.
 *
 * Written out from the exact definitions rather than pasted in as a decimal,
 * so there is no constant here that someone would later have to take on trust.
 */
const STANDARD_AREA_OVER_MASS =
  (Math.PI / 4) * (MM_PER_INCH / 1000) ** 2 / KG_PER_POUND;

export interface Projectile {
  /** Ballistic coefficient in the conventional lb/in², for `dragModel`. */
  ballisticCoefficient: number;
  dragModel: DragModel;
  /** Grams. Only needed for the energy column. */
  massG?: number;
}

export interface Wind {
  /** Positive blows the bullet to the shooter's right. m/s. */
  crossMs: number;
  /** Positive blows downrange, i.e. a tailwind. m/s. */
  alongMs: number;
}

export interface ShotSetup {
  muzzleVelocityMs: number;
  /** Barrel elevation relative to the line of sight, in milliradians. */
  launchAngleMrad: number;
  /** Height of the sight axis over the bore, in millimetres. */
  sightHeightMm: number;
  /** Elevation of the line of sight above horizontal, in milliradians. */
  lookAngleMrad?: number;
  wind?: Wind;
  atmosphere?: Atmosphere;
}

export interface TrajectoryPoint {
  /** Distance along the line of sight, metres. */
  rangeM: number;
  /** Vertical offset from the line of sight. Negative is below. Metres. */
  dropM: number;
  /** Horizontal offset from the line of sight. Positive is right. Metres. */
  windageM: number;
  velocityMs: number;
  timeS: number;
  mach: number;
  /** Present only when the projectile carries a mass. Joules. */
  energyJ?: number;
}

interface State {
  t: number;
  /** Downrange, vertical, lateral. Metres. */
  p: [number, number, number];
  /** m/s. */
  v: [number, number, number];
}

/**
 * Integration step, in metres of travel rather than seconds.
 *
 * Stepping by distance keeps the error roughly constant along the flight
 * instead of concentrating it at the muzzle where the bullet is fastest. At
 * 20 mm the solver agrees with the reference implementation to well inside the
 * tolerance the tests assert, and a full 1000 m solution still runs in a few
 * milliseconds — which matters because these run in an island on a phone.
 */
const STEP_M = 0.02;

function accelerationOf(
  v: [number, number, number],
  projectile: Projectile,
  atmosphere: Atmosphere,
  wind: Wind,
): [number, number, number] {
  // Air-relative velocity: a tailwind reduces the speed the projectile sees.
  const rx = v[0] - wind.alongMs;
  const ry = v[1];
  const rz = v[2] - wind.crossMs;
  const speed = Math.hypot(rx, ry, rz);
  if (speed === 0) return [0, -STANDARD_GRAVITY_MS2, 0];

  const cd = dragCoefficient(projectile.dragModel, machOf(speed, atmosphere));
  // a = ½ ρ v² Cd (A/m)_std / BC, acting against the air-relative direction.
  const magnitude =
    (0.5 * atmosphere.density * speed * speed * cd * STANDARD_AREA_OVER_MASS) /
    projectile.ballisticCoefficient;

  return [
    (-magnitude * rx) / speed,
    (-magnitude * ry) / speed - STANDARD_GRAVITY_MS2,
    (-magnitude * rz) / speed,
  ];
}

function rk4Step(
  state: State,
  dt: number,
  projectile: Projectile,
  atmosphere: Atmosphere,
  wind: Wind,
): State {
  const a1 = accelerationOf(state.v, projectile, atmosphere, wind);

  const v2: [number, number, number] = [
    state.v[0] + (a1[0] * dt) / 2,
    state.v[1] + (a1[1] * dt) / 2,
    state.v[2] + (a1[2] * dt) / 2,
  ];
  const a2 = accelerationOf(v2, projectile, atmosphere, wind);

  const v3: [number, number, number] = [
    state.v[0] + (a2[0] * dt) / 2,
    state.v[1] + (a2[1] * dt) / 2,
    state.v[2] + (a2[2] * dt) / 2,
  ];
  const a3 = accelerationOf(v3, projectile, atmosphere, wind);

  const v4: [number, number, number] = [
    state.v[0] + a3[0] * dt,
    state.v[1] + a3[1] * dt,
    state.v[2] + a3[2] * dt,
  ];
  const a4 = accelerationOf(v4, projectile, atmosphere, wind);

  const p: [number, number, number] = [0, 0, 0];
  const v: [number, number, number] = [0, 0, 0];
  for (let i = 0; i < 3; i += 1) {
    v[i] = state.v[i]! + (dt / 6) * (a1[i]! + 2 * a2[i]! + 2 * a3[i]! + a4[i]!);
    // Position uses the same weighted mean velocity, which is the standard
    // RK4 treatment of a second-order system written as a first-order pair.
    p[i] =
      state.p[i]! +
      (dt / 6) *
        (state.v[i]! +
          2 * (state.v[i]! + (a1[i]! * dt) / 2) +
          2 * (state.v[i]! + (a2[i]! * dt) / 2) +
          (state.v[i]! + a3[i]! * dt));
  }
  return { t: state.t + dt, p, v };
}

function initialState(setup: ShotSetup): State {
  const look = (setup.lookAngleMrad ?? 0) / 1000;
  const elevation = look + setup.launchAngleMrad / 1000;
  const sightHeight = setup.sightHeightMm / 1000;
  return {
    t: 0,
    // The bullet starts on the bore axis, which is `sightHeight` below the
    // line of sight. That is why every published table prints the sight height
    // as the "trajectory" figure at the muzzle.
    p: [0, -sightHeight, 0],
    v: [
      setup.muzzleVelocityMs * Math.cos(elevation),
      setup.muzzleVelocityMs * Math.sin(elevation),
      0,
    ],
  };
}

/** Distance along the line of sight, and vertical offset from it. */
function toSightFrame(state: State, lookAngleMrad: number): { range: number; drop: number } {
  const look = lookAngleMrad / 1000;
  if (look === 0) return { range: state.p[0], drop: state.p[1] };
  const range = state.p[0] * Math.cos(look) + state.p[1] * Math.sin(look);
  const sightLineHeight = state.p[0] * Math.tan(look);
  return { range, drop: state.p[1] - sightLineHeight };
}

function pointFrom(
  state: State,
  setup: ShotSetup,
  projectile: Projectile,
  atmosphere: Atmosphere,
): TrajectoryPoint {
  const { range, drop } = toSightFrame(state, setup.lookAngleMrad ?? 0);
  const speed = Math.hypot(state.v[0], state.v[1], state.v[2]);
  const point: TrajectoryPoint = {
    rangeM: range,
    dropM: drop,
    windageM: state.p[2],
    velocityMs: speed,
    timeS: state.t,
    mach: machOf(speed, atmosphere),
  };
  if (projectile.massG !== undefined) {
    point.energyJ = 0.5 * (projectile.massG / 1000) * speed * speed;
  }
  return point;
}

export interface SolveOptions {
  /** Ranges along the line of sight to report, metres. */
  atRangesM: number[];
  /** Stop early if the projectile falls this far below the line of sight. */
  maxDropM?: number;
}

/**
 * Integrates the flight and reports the state at each requested range.
 *
 * Requested ranges beyond where the solver stops — because the projectile has
 * fallen out of the sky or lost forward motion — are simply absent from the
 * result rather than being filled with an extrapolated guess.
 */
export function solveTrajectory(
  projectile: Projectile,
  setup: ShotSetup,
  options: SolveOptions,
): TrajectoryPoint[] {
  const atmosphere = setup.atmosphere ?? STANDARD_ATMOSPHERE;
  const wind = setup.wind ?? { crossMs: 0, alongMs: 0 };
  const lookAngle = setup.lookAngleMrad ?? 0;
  const targets = [...options.atRangesM].sort((a, b) => a - b);
  const maxDrop = options.maxDropM ?? 200;

  let state = initialState(setup);
  const out: TrajectoryPoint[] = [];
  let next = 0;

  // A requested range of 0 is the muzzle, which needs no integration.
  while (next < targets.length && targets[next]! <= 0) {
    out.push(pointFrom(state, setup, projectile, atmosphere));
    next += 1;
  }

  let guard = 0;
  const GUARD_LIMIT = 10_000_000;

  while (next < targets.length && guard < GUARD_LIMIT) {
    guard += 1;
    const speed = Math.hypot(state.v[0], state.v[1], state.v[2]);
    if (speed <= 0 || state.v[0] <= 0) break;

    const dt = STEP_M / speed;
    const candidate = rk4Step(state, dt, projectile, atmosphere, wind);
    const here = toSightFrame(state, lookAngle);
    const there = toSightFrame(candidate, lookAngle);

    if (there.range >= targets[next]!) {
      // Land exactly on the requested range with one fractional step, rather
      // than interpolating between two whole ones. The fraction is estimated
      // linearly and then integrated properly, so the reported point is a
      // solution of the same equations as every other point.
      const span = there.range - here.range;
      const fraction = span === 0 ? 0 : (targets[next]! - here.range) / span;
      const exact = rk4Step(state, dt * fraction, projectile, atmosphere, wind);
      out.push(pointFrom(exact, setup, projectile, atmosphere));
      next += 1;
      continue;
    }

    state = candidate;
    if (there.drop < -maxDrop) break;
  }

  return out;
}

/**
 * The barrel elevation that puts the bullet on the line of sight at a given
 * range — the arithmetic behind "zeroed at 100 m".
 *
 * Secant iteration on the drop at the zero range. Converges in a handful of
 * steps because drop is very nearly linear in launch angle over the range any
 * sight can be adjusted through.
 *
 * Returns `null` rather than a wrong answer when no elevation reaches the
 * range — a 9 mm asked to zero at 800 m has no solution, and the honest reply
 * to that is that there is none.
 */
export function solveZeroAngle(
  projectile: Projectile,
  setup: Omit<ShotSetup, 'launchAngleMrad'>,
  zeroRangeM: number,
  toleranceM = 0.0001,
): number | null {
  const dropAt = (launchAngleMrad: number): number | null => {
    const points = solveTrajectory(projectile, { ...setup, launchAngleMrad }, {
      atRangesM: [zeroRangeM],
      maxDropM: 1000,
    });
    return points.length === 1 ? points[0]!.dropM : null;
  };

  let a = 0;
  let b = 2;
  let fa = dropAt(a);
  let fb = dropAt(b);
  if (fa === null || fb === null) return null;

  for (let i = 0; i < 60; i += 1) {
    if (Math.abs(fb) < toleranceM) return b;
    if (fb === fa) return null;
    const next = b - (fb * (b - a)) / (fb - fa);
    if (!Number.isFinite(next) || next < -50 || next > 300) return null;
    const fNext = dropAt(next);
    if (fNext === null) return null;
    a = b;
    fa = fb;
    b = next;
    fb = fNext;
  }
  return Math.abs(fb) < toleranceM * 10 ? b : null;
}

export interface PointBlankSolution {
  /** The zero that produces the longest usable span. Metres. */
  zeroRangeM: number;
  /** The far end of that span. Metres. */
  maxRangeM: number;
  launchAngleMrad: number;
}

/**
 * The longest span over which the trajectory stays inside a stated radius of
 * the line of sight, and the zero that produces it.
 *
 * A **sighting** result, not a target-effect one: it answers "how far can I
 * hold dead centre and stay inside this circle", which is a question about the
 * arc of the bullet and the size of the mark. The radius is the caller's, and
 * the site never supplies one.
 */
export function maxPointBlankRange(
  projectile: Projectile,
  setup: Omit<ShotSetup, 'launchAngleMrad'>,
  targetRadiusM: number,
  searchToM = 500,
): PointBlankSolution | null {
  let best: PointBlankSolution | null = null;

  // Coarse sweep, then no refinement: the answer is quoted to the nearest few
  // metres in every published table because the inputs do not support more.
  for (let zero = 10; zero <= searchToM; zero += 5) {
    const angle = solveZeroAngle(projectile, setup, zero);
    if (angle === null) continue;

    const ranges: number[] = [];
    for (let r = 0; r <= searchToM * 1.5; r += 5) ranges.push(r);
    const points = solveTrajectory(projectile, { ...setup, launchAngleMrad: angle }, {
      atRangesM: ranges,
      maxDropM: targetRadiusM * 4,
    });

    let far = 0;
    let ok = true;
    for (const point of points) {
      if (point.dropM > targetRadiusM) {
        ok = false;
        break;
      }
      if (point.dropM < -targetRadiusM) break;
      far = point.rangeM;
    }
    // A zero that overshoots the radius is skipped, never used to end the
    // sweep: both a very short zero (a steep angle to climb to the sight line)
    // and a very long one (a steep angle to fight the drop) overshoot, and the
    // usable band sits between them.
    if (!ok) continue;
    if (!best || far > best.maxRangeM) {
      best = { zeroRangeM: zero, maxRangeM: far, launchAngleMrad: angle };
    }
  }

  return best;
}
